def split_into_sentences(s):
    import re
    parts = re.split(r'[.!?]', s)
    result = []
    for p in parts:
        stripped = p.strip()
        if stripped:
            result.append(stripped)
    return result

def group_consecutive_same_case(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return []
    result = []
    current = letters[0]
    for c in letters[1:]:
        if c.isupper() == current[-1].isupper():
            current += c
        else:
            result.append(current)
            current = c
    result.append(current)
    return result

def smallest_repeating_unit(s):
    n = len(s)
    if n == 0:
        return ''
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return unit
    return s

def is_repeated_pattern(s):
    n = len(s)
    if n == 0:
        return False
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return True
    return False

def count_repeating_unit_repeats(s):
    n = len(s)
    if n == 0:
        return 0
    for length in range(1, n):
        if n % length == 0:
            unit = s[:length]
            if unit * (n // length) == s:
                return n // length
    return 1

def letter_to_number_sum(s):
    total = 0
    for c in s:
        if c.isalpha():
            total += ord(c.lower()) - ord('a') + 1
    return total

def is_each_letter_increasing(s):
    letters = [c.lower() for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i] <= letters[i-1]:
            return False
    return True

def sum_of_letter_positions_per_word(s):
    words = s.split()
    result = []
    for w in words:
        total = 0
        for c in w:
            if c.isalpha():
                total += ord(c.lower()) - ord('a') + 1
        result.append(total)
    return result

def alphabet_position_pairs(s):
    result = []
    for c in s:
        if c.isalpha():
            pos = ord(c.lower()) - ord('a') + 1
            result.append((c, pos))
    return result

def make_acronym(phrase):
    words = phrase.split()
    result = ''
    for w in words:
        if w and w[0].isalpha():
            result += w[0].upper()
    return result

def acronym_word_start_indices(s):
    if s == '':
        return []
    words = s.split(' ')
    result = []
    idx = 0
    for w in words:
        result.append(idx)
        idx += len(w) + 1
    return result

def is_acronym_match(acronym, phrase):
    words = phrase.split()
    if len(words) != len(acronym):
        return False
    for a_char, w in zip(acronym, words):
        if not w or w[0].lower() != a_char.lower():
            return False
    return True

def camel_case_acronym(s):
    if not s:
        return ''
    result = s[0].upper()
    for c in s[1:]:
        if c.isupper():
            result += c
    return result

def concatenated_digit_value(s):
    digits = ''.join(c for c in s if c.isdigit())
    if not digits:
        return 0
    return int(digits)

def count_digit_transitions(s):
    digits = [int(c) for c in s if c.isdigit()]
    count = 0
    for i in range(1, len(digits)):
        if digits[i] > digits[i-1]:
            count += 1
    return count

def split_in_half(s):
    n = len(s)
    mid = (n + 1) // 2
    return (s[:mid], s[mid:])
